INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/accessLog/getDetail', '사용 이력 요청 전문 조회', '한 행의 요청 전문만 가져온다. 목록에 실을 수 없는 nclob 컬럼이며 상한에서 잘렸는지가 함께 실린다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/accessLog/getList', '사용 이력 목록 조회', '일어난 요청 전부를 최근 순으로 반환한다. 총 건수를 세지 않는 커서형이며 요청 전문은 실리지 않는다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/apiCatalog/getList', 'API 카탈로그 목록 조회', '등록된 업무 API 를 페이지 단위로 반환한다. API 마다 그것을 쓰는 메뉴 수가 함께 실리며 0 이면 미매핑이다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/apiCatalog/getMenuList', 'API 매핑 메뉴 조회', '선택한 API 를 쓰는 메뉴를 전량 반환한다. 메뉴 전체 경로와 사용 여부, 접근 가능 인원이 함께 실린다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/batchHistory/cancel', '배치 실행 중단 요청', '실행 중인 이력에 중단을 요청한다. 협조적 중단이라 즉시 멈추지 않을 수 있으며, 이미 요청된 건은 요청 시각을 덮지 않는다.', 'EXECUTE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/batchHistory/getDetail', '배치 실행 이력 상세 조회', '한 실행의 결과 상세와 예외 스택을 함께 가져온다. 남기지 않은 쪽은 비어 있고 화면이 그 탭을 비활성으로 둔다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/batchHistory/getList', '배치 실행 이력 조회', '실행 이력을 조건에 맞춰 반환한다. 소요 시간 정렬이 열려 있고 총 건수를 센다. 상세와 오류는 실리지 않는다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/batchSchedule/getBeanList', '실행 빈 목록 조회', '스프링 컨텍스트에 등록된 BatchJob 구현의 빈 이름을 반환한다. 사용 프로젝트가 구현을 넣기 전에는 비어 있다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/batchSchedule/getList', '배치 등록 목록 조회', '등록된 배치를 정렬 순서대로 반환한다. 다음 실행 시각과 최근 실행 결과가 함께 실린다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/batchSchedule/getRecentHistory', '이 배치의 최근 실행 이력', '한 배치의 최근 실행을 최신 순으로 반환한다. 화면이 10건을 요청하며 전량은 실행 이력 화면이 답한다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/batchSchedule/getTimezoneList', '시간대 후보 조회', '크론의 기준 시간대로 고를 수 있는 IANA 시간대 이름을 반환한다. 맨 앞이 서버의 업무 시간대이고 나머지는 오름차순이다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/batchSchedule/runNow', '배치 즉시 실행', '선택한 배치를 지금 실행한다. 쿨다운을 우회하며 이미 실행 중이면 그 건만 거절하고 노드와 시작 시각을 함께 반환한다.', 'EXECUTE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/batchSchedule/save', '배치 등록 저장', '추가·수정·삭제 행을 한 트랜잭션으로 반영한다. 크론과 쿨다운의 관계를 검증하고, 커밋 뒤에 스케줄러가 크론을 다시 건다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/code/getGroupList', '코드 그룹 목록 조회', '코드 그룹을 페이지 단위로 반환한다. 그룹마다 코드 수가 함께 실리며 삭제 게이트가 그것을 읽는다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/code/getList', '코드 목록 조회', '선택한 그룹의 코드를 전량 반환한다. 세션 언어의 코드명과 참조값 맵이 함께 실린다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/code/getRefDefList', '참조 코드 정의 목록 조회', '그룹이 쓰는 참조 코드 정의를 전량 반환한다. 이 목록이 곧 코드 그리드의 동적 컬럼 집합이다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/code/save', '코드 저장', '코드·코드명·참조값을 한 트랜잭션으로 반영한다. 코드명은 세션 언어의 메시지 행에 쓴다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/code/saveGroup', '코드 그룹 저장', '추가·수정·삭제 행을 한 트랜잭션으로 반영하고 코드 캐시 버전을 올린다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/code/saveRefDef', '참조 코드 정의 저장', '정의를 추가·수정·삭제한다. 삭제는 그 정의로 입력된 참조값을 함께 지운다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/config/getList', '시스템 환경설정 목록 조회', 'yml 이 정한 설정 키 전부를 SYS_CONFIG 오버라이드와 아우터 조인해 반환한다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/config/getPrefixes', '시스템 환경설정 접두사 목록 조회', '조회조건의 접두사 후보를 설정 키 전부에서 도출해 반환한다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/config/save', '시스템 환경설정 저장', '적용값 수정과 되돌리기(오버라이드 삭제)를 한 트랜잭션으로 반영하고 설정 캐시 버전을 올린다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/errorLog/getDetail', '에러 로그 상세 조회', '한 행의 스택트레이스와, 같은 추적 ID 의 요청 전문을 함께 가져온다. 4xx 는 스택이 없고 90일이 지난 요청은 전문이 없다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/errorLog/getList', '에러 로그 목록 조회', '예외가 난 요청을 최근 순으로 반환한다. 오류 코드와 완성된 문구가 함께 실리며 스택은 실리지 않는다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/loginLog/getList', '로그인 이력 목록 조회', '로그인 성공·실패와 세션 종료를 최근 순으로 반환한다. 총 건수를 세지 않는 커서형이다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/menu/deleteNode', '메뉴 삭제', '자식·매핑 API·매핑 역할·개인 예외가 모두 없을 때만 지운다. 즐겨찾기는 함께 지운다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/menu/getAccessibleUsers', '메뉴 사용 가능 사용자 조회', '이 메뉴에 닿는 사용자를 경유(역할·개인 예외)마다 한 행으로 반환한다. 만료된 부여도 상태와 함께 낸다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/menu/getApiList', '메뉴 매핑 API 조회', '이 메뉴가 쓰는 API 를 전량 반환한다. 0 건이면 이 화면의 기능을 아무도 쓸 수 없다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/menu/getRoleList', '메뉴 매핑 역할 조회', '이 메뉴에 권한을 준 역할을 전량 반환한다. 사용 안 함인 역할도 권한 행이 살아 있으므로 함께 낸다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/menu/getTree', '메뉴 트리 조회', '메뉴 전건을 전위 순회 순서로 반환한다. 매핑 API·접근 가능 인원·매핑 역할이 함께 실리며 삭제 게이트가 그것을 읽는다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/menu/save', '메뉴 속성 저장', 'URL·아이콘·사용 여부를 저장한다. 구조 노드의 사용 여부는 자손 전체에 같은 값을 쓴다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/menu/saveNode', '메뉴 노드 추가', '선택 노드의 자식으로 메뉴를 만든다. 선택이 없으면 최상위이며 순서는 형제의 맨 끝이다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/menu/saveTree', '메뉴 트리 저장', '드래그 결과를 형제 목록으로 받아 순서를 다시 쓴다. 보낸 목록이 현재 자식 집합과 다르면 거부한다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/message/getList', '다국어 메시지 목록 조회', '메시지 키를 페이지 단위로 반환한다. 키마다 지원 언어 전부의 값이 함께 실린다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/message/save', '다국어 메시지 저장', '생성된 키의 수정·삭제 행을 한 트랜잭션으로 반영하고 메시지 캐시 버전을 올린다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/notiRequest/getList', '요청함 목록 조회', '요청을 오래된 순으로 반환한다. 대기열이므로 오래 기다린 것이 먼저이며 기본 조건은 접수 상태다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/notiRequest/updateHandle', '요청 처리·반려', '선택한 요청을 처리 완료 또는 반려로 바꾸고 요청자에게 알림을 넣는다. 반려는 사유가 필수이며 이미 처리된 요청이 섞이면 전부 거부한다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/notice/getList', '공지사항 목록 조회', '공지를 고정 순서와 게시 시작 역순으로 반환한다. 게시 상태는 서버가 판정해 함께 싣는다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/notice/save', '공지사항 저장', '추가·수정·삭제 행을 한 트랜잭션으로 반영한다. 게시 기간과 팝업 기간의 포함 관계를 검증한다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/role/getList', '역할 목록 조회', '역할을 페이지 단위로 반환한다. 보유 인원·유효 인원·권한 건수가 함께 실리며 삭제 게이트가 그것을 읽는다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/role/save', '역할 저장', '추가·수정·삭제 행을 한 트랜잭션으로 반영하고, 사용 여부가 바뀐 역할의 보유자 세션에 권한 재계산을 예약한다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/roleAuth/getAffectedUsers', '역할 보유 사용자 조회', '이 역할을 가진 사용자를 페이지 단위로 반환한다. 부여 상태와 기간, 공집합 판정의 입력 둘이 함께 실린다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/roleAuth/getList', '역할 목록 조회', '권한을 부여할 역할을 고르는 목록이다. 비활성 역할도 함께 반환하며 보유 인원이 실린다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/roleAuth/getMenuTree', '역할 권한 트리 조회', '메뉴 계층 전건과 이 역할의 부여 상태를 반환한다. 메뉴마다 정의된 액션과 부여된 액션이 함께 실린다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/roleAuth/save', '역할 권한 저장', '이 역할의 권한을 보낸 집합으로 맞추고, 보유자 세션에 권한 재계산을 예약한다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/user/getEffectiveAuthList', '유효 권한 조회', '역할과 개인 예외를 출처별로 편 목록을 반환한다. 메뉴 게이트와 지금 실제로 효력이 있는지가 행마다 실리며, 전체 메뉴 모드에서는 부여가 없는 메뉴도 나온다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/user/getIpList', '접속 허용 IP 조회', '한 사용자의 허용 대역을 반환한다. 꺼진 행도 포함하며, 행이 하나도 없으면 그 계정에는 제한이 없다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/user/getList', '사용자 목록 조회', '계정을 페이지 단위로 반환한다. 접근 제어 체인으로 계산한 계정 상태가 함께 실리며 원본 네 컬럼도 같이 온다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/user/getRoleCandidates', '역할 후보 조회', '부여할 수 있는 역할 전건을 이름 순으로 반환한다. 꺼진 역할도 포함하며 사용 여부가 함께 실린다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/user/getRoleList', '보유 역할 조회', '한 사용자의 역할 부여를 기간과 함께 반환한다. 만료된 부여와 꺼진 역할의 부여도 포함하며 역할 자체의 사용 여부가 함께 실린다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/user/getSessionList', '활성 세션 조회', '한 사용자의 살아 있는 세션을 최근 접근이 늦은 것부터 반환한다. 이 요청의 세션에는 표시가 붙는다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/user/getUserMenuAuth', '개인 예외 조회', '한 사용자의 개인 예외를 메뉴 경로·기간·사유와 함께 반환한다. 조회 전용이며 부여는 개인 예외 권한 화면의 일이다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/user/killSession', '세션 강제 종료', '고른 세션을 스토어에서 지운다. 자기 계정의 세션은 거부하며 이미 끊긴 세션은 건너뛴다. 계정 자체는 바뀌지 않는다.', 'EXECUTE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/user/save', '사용자 저장', '추가·수정 행을 한 트랜잭션으로 반영한다. 삭제는 받지 않으며 신규 계정의 임시 비밀번호를 돌려준다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/user/saveDormantRelease', '휴면 해제', '배치가 건 휴면 플래그를 관리자가 내린다. 잠금은 함께 풀리지 않는다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/user/saveIp', '접속 허용 IP 저장', '추가·수정·삭제 행을 한 트랜잭션으로 반영한다. 형식이 IP 또는 CIDR 이어야 하며 전부 지우면 제한 없음이 된다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/user/savePasswordReset', '임시 비밀번호 발급', '정책을 충족하는 임시 비밀번호를 만들어 계정에 넣고 강제 변경 상태로 표시한다. 잠금은 풀리지 않는다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/user/saveRole', '보유 역할 저장', '추가·수정·삭제 행을 한 트랜잭션으로 반영하고, 그 사용자의 세션에 권한 재계산을 예약한다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/user/saveUnlock', '계정 잠금 해제', '연속 로그인 실패로 잠긴 계정을 푼다. 잠금 플래그와 실패 횟수만 쓰고 사용 여부·휴면은 건드리지 않는다.', 'SAVE', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/userAuth/getList', '사용자 목록 조회', '개인 예외를 부여할 사용자를 고르는 목록이다. 못 쓰는 계정도 함께 반환하며 계정 상태가 실린다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/userAuth/getMenuTree', '개인 예외 권한 트리 조회', '메뉴 계층 전건과 이 사용자의 개인 예외를 기간·사유까지 반환한다. 역할로 이미 갖고 있는 액션도 함께 실린다.', 'READ', NULL, NULL, NULL, NULL);
INSERT INTO sys_api (api_url, api_nm, api_desc, action_cd, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('/api/system/service/userAuth/save', '개인 예외 저장', '추가·수정·삭제 행을 한 트랜잭션으로 반영하고, 그 사용자의 세션에 권한 재계산을 예약한다.', 'SAVE', NULL, NULL, NULL, NULL);
