INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.anonymous', 'FRONT', '사용자 칸이 빈 행의 표시 — screen/admin/system/log/access/requirements.md. 빈칸으로 두면 *수집이 안 된 것*과 구분되지 않는다. 미인증 요청에 `USER_ID` 가 없는 것은 정상이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.col.clientIp', 'FRONT', 'IP 컬럼.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.col.creDtm', 'FRONT', '일시 컬럼 — 정렬이 열린 유일한 컬럼이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.col.httpStat', 'FRONT', '상태 컬럼 — 응답의 HTTP 상태. 전 요청을 받으므로 필요하다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.col.menu', 'FRONT', '메뉴 컬럼 — 코드가 아니라 메뉴명으로 그린다(sys/code.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.col.payload', 'FRONT', '전문 컬럼 — 값이 아니라 `[보기]` 다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.col.requestUri', 'FRONT', '요청 URI 컬럼.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.col.seq', 'FRONT', '순번 컬럼 — tie-breaker 이며 기본 숨김이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.col.traceId', 'FRONT', '추적 ID 컬럼 — 5xx 토스트의 그 값이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.col.userId', 'FRONT', '사용자 아이디 컬럼 — 미인증 요청은 #ACCESS_LOG_ANONYMOUS 다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.col.userNm', 'FRONT', '사용자명 컬럼 — `SYS_USER` 를 조인해 얻는다(2026-09-01). 미인증 요청과 지워진 계정에서 비며, 그 자리를 채우지 않는다 — 바로 왼쪽 칸이 이미 `(익명)` 이라고 말하고 있어 이 칸의 빈칸은 덧말이다. 로그인 이력이 `없는 계정` 배지를 붙이는 것과 갈리는 자리다(거기는 없는 계정이 흔한 일이다). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.empty', 'FRONT', '0건일 때 — 보존 기간을 함께 말한다(screen/admin/system/log/access/requirements.md). *"조회 결과가 없습니다"* 로 끝내면 조건이 좁은 것인지 거기 데이터가 없는 것인지 구분되지 않는다. 0건에는 언제나 이유가 있고 화면이 아는 이유는 화면이 말한다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.footer.range', 'FRONT', '푸터 왼쪽의 덧붙임 — `{days}`. 총 건수를 잃은 자리를 메운다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.grid.title', 'FRONT', '마스터 그리드의 제목 — 이 화면에 그리드가 하나다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.menu.clientClaim', 'FRONT', '메뉴 컬럼 헤더의 툴팁 — 클라이언트가 밝힌 값이다(backend/packages.md). 붙이지 않으면 이 화면의 메뉴별 집계가 감사 근거로 인용된다(screen/admin/system/log/access/requirements.md). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.noMenu', 'FRONT', '메뉴 문맥 없는 요청의 표시 — 로그인·하트비트가 그렇다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.outcome.failure', 'FRONT', '상태 조건의 항목 — 4xx·5xx.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.outcome.success', 'FRONT', '상태 조건의 항목 — 2xx·3xx.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.payload.length', 'FRONT', '전문 모달 하단의 글자 수 — `{count}`(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.payload.link', 'FRONT', '전문 셀에 그려지는 글자 — 값이 아니다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.payload.title', 'FRONT', '전문 모달의 제목.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.payload.truncated', 'FRONT', '전문이 상한에서 잘렸다 — backend/packages.md. 말하지 않으면 잘린 JSON 을 받은 사람이 *"저장이 깨졌다"* 로 읽는다. 이 화면에서 가장 흔한 오독이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.search.clientIp', 'FRONT', '조회조건 — IP. 완전 일치다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.search.menu', 'FRONT', '', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.search.menuCd', 'FRONT', '조회조건 — 메뉴 코드. 뿌리 테이블의 컬럼이라 값 비교 하나로 끝난다. `메뉴 없음` 항목이 여기 없다. 콤보였을 때는 `in` 배열의 `null` 이 `IS NULL` 로 펴졌는데(screen/admin/system/log/access/requirements.md) 텍스트 칸에는 담을 자리가 없다 — 그 물음은 메뉴 컬럼의 필터가 답한다(frontend/grid.md). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.search.menuNm', 'FRONT', '조회조건 — 메뉴명. 이름은 두 테이블 건너에 있다(sys/code.md). `SYS_MENU.MENU_NM` 이 담은 것은 메시지 키이고 이름은 `SYS_MESSAGE` 의 값이라 서버가 `EXISTS` 로 푼다. 어느 언어든 걸린다 — 운영자는 화면에 보이는 그 이름을 들고 오지 어느 언어의 값인지를 들고 오지 않는다(screen/admin/system/code/requirements.md). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.search.outcome', 'FRONT', '조회조건 — 상태. 파생이며 기본은 전체다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.search.period', 'FRONT', '조회조건 — 기간. 필수이며 상한이 31일이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.search.requestUri', 'FRONT', '조회조건 — 요청 URI. 앞 일치다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.search.traceId', 'FRONT', '조회조건 — 추적 ID. 넣으면 기간이 선택이 된다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.search.userId', 'FRONT', '조회조건 — 사용자 아이디. 문자열 비교 넷(같음 · 시작 · 포함 · 끝)이다(2026-09-01). 인덱스가 없는 것은 그대로인데 기간이 먼저 좁힌다(screen/admin/system/log/access/requirements.md) — 완전 일치만 열어 두면 조각을 든 사람이 기간을 넓혀 훑고, 그것이 더 비싸다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('accessLog.search.userNm', 'FRONT', '조회조건 — 사용자명. 이름은 `SYS_USER` 조인이 답한다(2026-09-01).', NULL, NULL, NULL, NULL);
