INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('apiCatalog.col.menuUseYn', 'FRONT', '하단 — 메뉴의 사용 여부. 꺼져 있으면 매핑이 살아 있어도 소용없다(backend/security.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('apiCatalog.col.seedDtm', 'FRONT', '감사 컬럼의 라벨 — 최종 시드 반영이다. *등록일* 이 아니다(screen/menu/requirements.md). 시드는 전건 삭제 후 전건 삽입이라(seed.md) 전 행이 같은 값이며, 뜻은 *"이 배포에서 시드가 다시 쓰인 시각"* 이다. 라벨이 그 기대를 만든다. /', NULL, NULL, NULL, NULL);
