INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('apiCatalog.notRegistered', 'FRONT', '여기가 진단이다 — URL 칸에만 값을 넣었는데 0건일 때(screen/menu/requirements.md). 미등록은 화면이 보여줄 수 없다 — 없는 행을 목록에 낼 방법이 없기 때문이다. *"조회 결과가 없습니다"* 로 끝내면 이 화면의 세 갈래 중 하나가 사라진다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('apiCatalog.search.actionCd', 'FRONT', '조회조건 — 액션. 기본은 전체다.', NULL, NULL, NULL, NULL);
