INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('apiCatalog.search.apiUrl', 'FRONT', '조회조건 — API URL. 로그에서 얻은 URL 하나가 들어오는 칸이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('apiCatalog.search.mapped', 'FRONT', '조회조건 — 매핑 상태. 진단의 입구다(screen/menu/requirements.md). 컬럼 필터로 두면 현재 페이지 안에서만 걸리므로(frontend/grid.md) 서버 조건이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('apiCatalog.unmapped', 'FRONT', '매핑 메뉴 `0` 에 붙는 배지 — screen/menu/requirements.md 의 `미연결` 과 같은 어휘, 다른 뜻이다. 둘 다 *"연결이 끊겼다"* 이고 고치는 곳만 다르다 — 미연결은 프론트 라우트, 미매핑은 `endpoints.ts` 와 시드다. 화면이 둘이어도 사용자가 배우는 것은 하나다. /', NULL, NULL, NULL, NULL);
