INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('batch.rslt.LOST', 'FRONT', '실행하던 노드가 사라져 결과를 모른다 — 배지 `err` (screen/admin/system/batch/schedule/requirements.md). `FAIL` 과 가르는 이유는 스택이 없다는 것이다. 죽은 것은 배치가 아니라 프로세스이고, 같은 색을 쓰되 다른 글자여야 스택을 찾다 못 찾은 사람이 *로그가 유실됐다* 로 잘못 결론짓지 않는다. /', NULL, NULL, NULL, NULL);
