INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('batchHistory.cancel.done', 'FRONT', '결과 — `{count}` 건에 요청했다. 멈추는 시점은 배치의 체크포인트다.', NULL, NULL, NULL, NULL);
