INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('batchSchedule.run.rejectedNode', 'FRONT', '거절 — `{batchId}` `{node}` `{time}`. 노드와 시각이 요점이다(screen/admin/system/batch/schedule/requirements.md). *"실행 중입니다"* 만 내면 운영자는 얼마나 기다려야 하는지 모른다 — backend/persistence.md 이 `NODE_ID` 를 남긴 것과 같은 이유다. /', NULL, NULL, NULL, NULL);
