INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.col.grpNm', 'FRONT', '그룹명 컬럼 — 다국어가 아니다. 관리 화면 전용 명칭이라 컬럼 값이다(sys/code.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.col.refCd', 'FRONT', '참조 코드 컬럼 — `CODE_REF_KEY` 화이트리스트에서 고른다(sys/code.md).', NULL, NULL, NULL, NULL);
