INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.col.sysYn', 'FRONT', '시스템 여부 컬럼 — 읽기 전용이다. 왜 못 지우는지가 눌러 보기 전에 보인다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.col.useYn', 'FRONT', '사용 여부 컬럼 — 스위치다(frontend/grid.md). 시스템 행에서는 잠긴다(screen/admin/system/code/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.delete.refWarn', 'FRONT', '코드 삭제 저장 전 확인 — `{count}`. 참조값은 그 행의 파생이라 함께 지운다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.detail.empty', 'FRONT', '마스터에서 그룹을 고르기 전 하단의 빈 상태(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.detail.locked', 'FRONT', '미저장 신규 그룹을 골랐을 때 — 잠긴 상태다(frontend/grid.md). 부모 키가 아직 DB 에 없어 자식을 붙일 수 없다. screen/admin/system/code/requirements.md 의 메시지 화면이 이 규칙을 비껴간 것은 하단이 DB 에 붙지 않아서였고, 여기 하단은 자기 테이블에 FK 로 붙어 있다 — 2단계 등록을 그대로 치른다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.detail.title', 'FRONT', '하단 그리드의 제목 — 고른 그룹의 코드다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.group.hasCode', 'FRONT', '그룹 삭제가 잠긴 이유 — `{count}`. 회색 체크박스만 두면 버그로 읽힌다(screen/admin/system/code/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.group.title', 'FRONT', '마스터 그리드의 제목 — 코드 그룹이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.refDef.button', 'FRONT', '하단 ⓐ의 버튼 — 서버를 부르지 않고 모달을 연다(frontend/grid.md · screen/admin/system/code/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.refDef.deleteWarn', 'FRONT', '정의 삭제 저장 전 확인 — `{count}`. 값 → 정의 순서라 FK 가 거부하지 않는다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.refDef.dirty', 'FRONT', '정의 버튼이 잠긴 이유 — 미저장 편집이 있다(screen/admin/system/code/requirements.md). 정의가 바뀌면 컬럼 집합이 바뀌고 하단 재조회가 편집을 버린다. 열고 나서 묻는 것보다 누를 수 없는 것이 먼저 보이는 편이 낫고, 그 사유를 말한다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.refDef.grid', 'FRONT', '정의 모달 안 그리드의 제목.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.refDef.noGroup', 'FRONT', '그룹을 고르지 않은 채 정의를 열려 했을 때.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.refDef.title', 'FRONT', '정의 모달의 제목 — `{grpNm}` 이 어느 그룹의 것인지를 말한다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.search.codeNm', 'FRONT', '조회조건 — 코드명. 이름은 `SYS_MESSAGE` 에 있고 어느 언어든 걸린다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.search.dtlCd', 'FRONT', '조회조건 — 코드. 하단 조건이 마스터를 거른다(screen/admin/system/code/requirements.md). *"이 코드값이 어느 그룹에 있더라"* 가 실제로 자주 묻는 것이며, 고르면 하단이 그 조건으로 미리 걸려 있다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('codeMgmt.search.grpCd', 'FRONT', '조회조건 — 그룹 코드.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('config.adminReset.warn', 'FRONT', '`auth.password.admin-reset-enabled` 를 끌 때 — sys/code.md. 되돌릴 수는 있지만 되돌릴 사람이 못 들어올 수 있다. 메일 연동이 없는 배포에서 잠긴 계정을 푸는 유일한 경로다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('config.col.cfgDesc', 'FRONT', '설명 컬럼 — 필드 Javadoc 에서 온다. `CFG_DESC` 가 아니다(screen/admin/system/config/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('config.col.cfgKey', 'FRONT', '키 컬럼 — PK 이고 코드가 정한다. 열리지 않는다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('config.col.cfgType', 'FRONT', '유형 컬럼 — 필드 타입에서 온다. 읽기 전용.', NULL, NULL, NULL, NULL);
