INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('config.col.defaultVal', 'FRONT', '기본값 컬럼 — `yml` 이며 언제나 있다. 숨기지 않는다(screen/admin/system/config/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('config.col.revert', 'FRONT', '삭제 컬럼의 헤더 — 되돌리기 다(screen/admin/system/config/requirements.md). *삭제* 면 관리자는 값이 사라질 것을 기대하고, 목록에 같은 키가 남아 있으면 버그로 읽는다 — 기대를 라벨이 만든다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('config.defaulted', 'FRONT', '조회조건의 반대쪽 — 오버라이드 행이 없는 키.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('config.grid.title', 'FRONT', '그리드의 제목 — 단일 그리드다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('config.overridden', 'FRONT', '적용값 뒤에 붙는 배지 — 근거는 `SYS_CONFIG` 행의 존재다(screen/admin/system/config/requirements.md). 값이 기본값과 같아도 붙는다. 같은 값으로 저장해 두면 다음 배포가 기본값을 올려도 그 키만 옛 값에 묶이며, 눈으로는 구분되지 않으므로 이것이 유일한 신호다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('config.revert.warn', 'FRONT', '되돌리기 확인 — `{key}` · `{defaultVal}`. 기본값을 함께 말한다(screen/admin/system/config/requirements.md). 값이 사라지는 것이 아니라 `yml` 이 드러난다는 것을 미리 말해 두지 않으면, 되돌린 뒤에도 목록에 남은 같은 키가 "지웠는데 그대로다" 로 읽힌다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('config.search.keyword', 'FRONT', '조회조건 — 키와 설명을 한 칸이 함께 건다(sys/code.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('config.search.overridden', 'FRONT', '조회조건 — 변경 여부. 판정은 행의 존재다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('config.search.prefix', 'FRONT', '조회조건 — 접두사. 전 키에서 도출한다(screen/admin/system/config/requirements.md).', NULL, NULL, NULL, NULL);
