INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.api-not-registered', 'BACK', 'SYS_API 에 행이 없다. 고치는 곳은 API 마스터 시드다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.batch-hist.not-cancelable', 'BACK', '중단 대상이 아니다 — RUNNING 이 아니다(screen/admin/system/batch/schedule/requirements.md). 화면이 eligible 로 이미 걸렀지만 그것은 고른 시점의 사실이고, 그 사이 배치가 끝났을 수 있다. 조용히 건너뛰지 않고 거절하는 쪽이 맞다 — 끝난 행에 요청을 세우면 영원히 응답하지 않을 요청이 이력에 남는다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.batch-hist.purged', 'BACK', '[보기] 를 눌렀는데 그 사이 파기됐다 — 보존 1년(retention.md · screen/admin/system/batch/schedule/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.batch.already-running', 'BACK', '즉시 실행이 거부됐다 — 이미 실행 중이다(screen/admin/system/batch/schedule/requirements.md). 거부 사유가 이것 하나다. 쿨다운은 수동이 우회하고, USE_YN=''N'' 은 막지 않는다 — 꺼 둔 배치를 한 번 돌려 보는 것이 정상 동선이다. 문구에 노드와 시각이 들어간다. "실행 중입니다" 만 내면 운영자는 얼마나 기다려야 하는지 모른다 — backend/persistence.md 이 NODE_ID 를 남긴 것과 같은 이유다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.batch.bean-unknown', 'BACK', '실행 빈이 없거나 등록된 BatchJob 구현이 아니다 — screen/admin/system/batch/schedule/requirements.md. 화면은 셀렉트로 고르게 해서 이 경로를 닫지만, 화면 밖 경로는 그 셀렉트를 지나지 않는다. 막지 않으면 실행 시점에 터지고 그때는 크론이 깨운 새벽이다(원칙 P1). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.batch.cooldown-too-long', 'BACK', '쿨다운이 크론 최소 간격보다 길다 — backend/persistence.md 이 등록 거부 로 정한 그것. 같은 값이어도 거부한다 — 경계에서 한 주기가 통째로 누락될 수 있다. 이 조건이 막으려는 사고가 실행이 조용히 건너뛰어진다 이며, 조용하기 때문에 저장 시점에 막는 것 말고는 알릴 자리가 없다. 오류가 두 셀에 걸린다(screen/admin/system/batch/schedule/requirements.md) — 어느 쪽이 틀렸는지 서버가 말할 수 없다. 틀린 것은 값이 아니라 관계이며, 그래서 문구가 두 값을 함께 읽어 준다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.batch.cron-invalid', 'BACK', '크론 표현식을 파서가 읽지 못했다 — 스케줄러가 쓰는 그 파서다(screen/admin/system/batch/schedule/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.batch.desc-required', 'BACK', '설명을 비운 채 저장했다 — sys/batch.md · screen/admin/system/batch/schedule/requirements.md. 설명이 필수인 유일한 테이블이다. 끄는 확인 창이 이 문장을 그대로 읽어 주며 (screen/admin/system/batch/schedule/requirements.md), 비어 있으면 그 확인이 아무 말도 하지 않는다 — 운영자가 배치를 끄는 순간은 대개 장애 대응 중이고 그때 소스를 열 시간은 없다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.batch.duplicate', 'BACK', 'BATCH_ID 중복 — PK 이자 락 키다(backend/persistence.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.batch.name-required', 'BACK', '배치명을 비운 채 저장했다 — screen/admin/system/batch/schedule/requirements.md 의 필수 컬럼.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.batch.not-deletable', 'BACK', '지울 수 없다 — 켜져 있거나 실행 중이다(screen/admin/system/batch/schedule/requirements.md). 실행 이력은 게이트가 아니다. 이력에 FK 가 없으므로(sys/batch.md) 등록을 지워도 행은 남으며 남아야 한다 — 이력이 게이트가 되면 오래된 배치는 영영 못 지운다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.batch.not-found', 'BACK', '없는 등록을 가리켰다. 화면이 낡았거나 화면 밖 경로다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.batch.param-json', 'BACK', 'PARAM_JSON 이 JSON 이 아니다 — 프론트도 보고 서버도 본다(screen/admin/system/batch/schedule/requirements.md · frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.batch.timezone-invalid', 'BACK', '아는 시간대 이름이 아니다 — screen/admin/system/batch/schedule/requirements.md §6-1 의 13. 화면은 셀렉트라 이 값이 만들어지지 않는다. API 를 직접 부르는 경로의 마지막 방어이며, 고정 오프셋(+09:00)도 여기서 걸린다 — 파싱은 되지만 서머타임이 없어 현지 시각을 유지한다 는 그 컬럼의 목적을 조용히 깬다(backend/time.md). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.code.duplicate', 'BACK', '이미 있는 (GRP_CD, DTL_CD) 로 신규 행을 저장했다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.code.group-duplicate', 'BACK', '이미 있는 GRP_CD 로 신규 행을 저장했다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.code.group-has-code', 'BACK', '코드가 남아 있어 그룹을 지울 수 없다 — 조회 뒤에 누군가 추가했다(screen/admin/system/code/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.code.group-missing', 'BACK', '고치거나 지우려는 그룹이 이미 없다 — 다른 사람이 먼저 지웠다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.code.missing', 'BACK', '고치거나 지우려는 코드가 이미 없다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.code.ref-cd-unknown', 'BACK', 'CODE_REF_KEY 화이트리스트 밖의 참조 코드다 — 소스가 이 값을 문자열로 참조한다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.code.ref-def-duplicate', 'BACK', '이미 있는 (GRP_CD, REF_CD) 정의를 다시 만들려 했다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.code.ref-def-unknown', 'BACK', '그 그룹에 정의되지 않은 참조 코드로 값을 보냈다 — 화면이 만들 수 없는 조합이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.code.required', 'BACK', '그룹명·코드값 같은 필수 값이 비었다. 화면도 막지만 판정은 서버에도 있다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.code.system-locked', 'BACK', '시스템 코드(SYS_YN=''Y'')를 지우거나 끄려 했다 — sys/code.md.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.config.invalid-value', 'BACK', '재바인딩이 값을 거부했다 — 타입·@Min·상호 제약이 전부 여기로 온다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.config.key-unknown', 'BACK', '코드가 정하지 않은 CFG_KEY 가 왔다 — 아우터 조인의 왼쪽에 없는 키다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.config.not-overridden', 'BACK', '되돌리려는데 오버라이드 행이 없다 — 다른 사람이 먼저 되돌렸다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.conflict', 'BACK', '다른 사용자가 먼저 같은 값을 저장했다 — DB 제약이 막은 경우다. 화면의 중복 검사도 서버의 존재 확인도 읽은 시점과 쓰는 시점 사이를 막지 못한다. 그 틈으로 들어온 것이 여기로 오며, 사용자가 할 일은 다시 조회다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.error-log.purged', 'BACK', '상세를 열려는데 그 행이 없다 — 조회 뒤에 파기 배치가 지나갔다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.error-log.range-required', 'BACK', '기간 없이 조회하려 했다 — 추적 ID 를 넣으면 건너뛴다(이 화면의 주된 동선이다).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.error-log.range-too-wide', 'BACK', '기간이 92일을 넘었다 — 보존은 180일이라 잘라 주면 못 본 절반이 남는다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.forbidden', 'BACK', '인가 거부의 기본 문구. 원인 넷이 이 하나를 공유한다(backend/security.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.internal', 'BACK', '처리하지 못한 예외. 사용자에게는 traceId 하나만 나간다(backend/security.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.lock.conflict', 'BACK', '같은 자원을 다른 작업이 잡고 있다. 경합은 정상이므로 400 대다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.login-log.range-required', 'BACK', '기간 없이 조회하려 했다 — 보존이 1년이라 조건 없이 열면 그 전량을 향한다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.login-log.range-too-wide', 'BACK', '기간이 92일을 넘었다 — 보존(1년)보다 창이 짧은 유일한 화면이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.login.concurrent', 'BACK', 'prevent-login: true 에서 기존 세션이 살아 있어 신규 로그인을 거부했다.', NULL, NULL, NULL, NULL);
