INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.login.expired', 'BACK', '사용 기간이 지난 계정.', NULL, NULL, NULL, NULL);
