INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.login.ip-denied', 'BACK', '허용되지 않은 IP 에서의 접속.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.login.locked', 'BACK', '연속 실패로 잠긴 계정. 재설정으로 풀린다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.login.no-authority', 'BACK', '유효 권한이 공집합이라 로그인시키지 않는다 — 빈 셸로 들여보내지 않는다(backend/security.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.login.temp-expired', 'BACK', '임시 비밀번호의 유효 시간이 지났다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.malformed-body', 'BACK', '요청 본문을 파싱하지 못했다. 어느 필드인지는 알 수 없다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.menu.child-under-leaf', 'BACK', 'URL 이 있는 노드 아래에 자식을 만들거나 옮기려 했다 — 〃.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.menu.cycle', 'BACK', '자기 자신 또는 자손 아래로 옮기려 했다 — 순환 네 층 중 저장 서비스(sys/menu.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.menu.depth', 'BACK', '리프 포함 5단을 넘는다 — 서브트리를 통째로 옮기면 그 높이까지 더해 본다(sys/menu.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.menu.duplicate', 'BACK', 'MENU_CD 중복 — 다른 사람이 방금 만든 것을 클라이언트가 알 수 없다(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.menu.not-deletable', 'BACK', '삭제 게이트 — 자식·매핑 API·매핑 역할·개인 예외 중 하나라도 남아 있다(screen/menu/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.menu.not-found', 'BACK', '없는 메뉴를 가리켰다. 화면이 낡았거나 화면 밖 경로다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.menu.tree-changed', 'BACK', '보낸 형제 목록이 지금의 자식 집합과 다르다 — sys/menu.md 의 집합 검증. 나머지와 성질이 다르다: 해서는 안 되는 일이 아니라 보던 트리가 낡았다 이며, 조회 한 번이 복구다. 문구가 그 한 줄을 말한다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.menu.url-duplicate', 'BACK', '다른 메뉴가 이미 가진 URL 을 저장하려 했다 — 메뉴 URL은 화면 하나와만 연결된다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.menu.url-on-parent', 'BACK', '자식이 있는 노드에 URL 을 채우려 했다 — URL 과 자식은 배타다(backend/security.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.menu.url-required', 'BACK', '권한 행이 있는 노드의 URL 을 비우려 했다 — screen/menu/requirements.md. 비우는 순간 권한 대상이 아닌데 SYS_ROLE_MENU_AUTH 에 행이 남는다 — sys/menu.md 가 "들어오면 거부" 라고 한 상태가 거꾸로 만들어진다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('excel.upload.notYn', 'FRONT', '`Y`/`N` 이 아니다 — `{value}`.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.message.key-create-forbidden', 'BACK', '메시지 키는 소스 상수와 시드 생성기만 만들며 관리 API의 신규 행은 거부한다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.message.key-duplicate', 'BACK', '이미 있는 MSG_KEY 로 신규 행을 저장했다. 현재 페이지 밖은 화면이 모른다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.message.key-missing', 'BACK', '저장하려는 키가 이미 지워졌다 — 다른 사람이 먼저 지웠다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.message.lang-unknown', 'BACK', '지원하지 않는 언어의 값이 왔다. 지원 언어 목록은 서버가 갖는다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.method-not-allowed', 'BACK', '허용되지 않은 HTTP 메서드. 서버 고장이 아니라 클라이언트 잘못이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.no-authority', 'BACK', 'API 는 정상이고 이 사람에게 권한이 없다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.not-found', 'BACK', '없는 자원 · 오타 난 API 경로.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.noti-inbox.not-found', 'BACK', '내 알림이 아니다 — 남의 번호이거나 이미 파기됐다(보존 90일 · retention.md). 둘을 갈라 말하지 않는다. "남의 것" 이라고 답하면 그 번호가 실재한다는 사실을 알려 주게 되고, 알림은 사람마다 행이 다르므로(sys/notification.md) 그 사실 자체가 정보다. 조용히 넘기지 않는 이유는 화면이 읽음으로 바뀐 줄 알고 배지를 깎기 때문이다 — 새로고침하면 숫자가 되돌아온다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.noti-req.content-required', 'BACK', '요청 내용이 비었다 — sys/notification.md 이 REQ_CONTENT 를 필수로 두었다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.noti-req.duplicate', 'BACK', '같은 유형의 접수 상태 요청이 이미 있다. 워크플로가 없으므로 요청은 한 번 내면 답이 올 때까지 그대로다 — 같은 것을 또 내도 진행이 빨라지지 않고 대기열만 늘어난다. 그리고 관리자는 그 여벌을 하나씩 반려해야 하는데, 반려마다 요청자에게 알림이 나간다(screen/admin/system/notice/requirements.md). 막는 것은 같은 유형뿐이다. 권한 신청과 잠금 해제는 서로 다른 답을 기다리는 것이라 함께 열려 있어야 한다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.noti-req.memo-required', 'BACK', '반려인데 사유가 비었다 — sys/notification.md 이 필수로 정했다. 사유 없는 반려는 요청자에게 아무 정보도 주지 않는다. 그러면 같은 요청을 다시 내고, 그것이 워크플로를 만들지 않기로 한 대가를 실제 비용으로 바꾼다 — 단계가 없으므로 한 번의 답이 전부여야 한다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.noti-req.not-found', 'BACK', '없는 요청이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.noti-req.not-received', 'BACK', '이미 처리된 요청이 선택에 섞였다 — screen/admin/system/notice/requirements.md. 처리 가능한 것만 골라 실행하지 않는다. 일부만 처리하면 알림이 일부에게만 나가고 사용자는 무엇이 처리됐는지 모른다 — 되돌리는 길이 없으므로 부분 성공을 만들지 않는다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.notice.not-found', 'BACK', '없는 공지다 — 화면이 낡았거나 화면 밖 경로다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.notice.period', 'BACK', '게시 종료가 시작보다 앞이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.notice.popup-period', 'BACK', '팝업을 켰는데 팝업 기간이 비었다 — screen/admin/system/notice/requirements.md.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.notice.popup-range', 'BACK', '팝업 기간이 게시 기간을 벗어났다 — screen/admin/system/notice/requirements.md. 이 검증이 없으면 목록에 없는 공지가 팝업으로 뜬다. 팝업의 "공지 N건 더 있음" 링크가 알림 모달의 공지 탭을 여는데 그 탭은 게시 기간을 보므로, 눌러도 그 공지가 없다 — 팝업이 도달 보장 장치라는 전제가 거기서 깨진다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.notice.required', 'BACK', '제목·본문·게시 시작이 비었다 — 셀 단위 오류로 돌려준다(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.password-change-required', 'BACK', '제한 세션. 비밀번호를 바꾸면 풀리므로 이것만 문구가 다르다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.query.cursor-sort-arity', 'BACK', '커서형에 정렬 컬럼이 둘 이상 왔다 — 기준점이 성립하려면 정렬 키가 하나여야 한다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.query.invalid-cursor', 'BACK', '커서를 읽을 수 없다. 조용히 첫 장으로 떨어뜨리면 데이터가 없다 로 읽힌다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.query.not-sortable', 'BACK', '.sortable() 이 없는 필드로 정렬을 요청했다. 파생·긴 텍스트가 그렇다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.query.op-type', 'BACK', '연산자가 그 필드의 타입을 받지 않는다 — 숫자 필드의 contains 같은 것.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.query.too-many-rows', 'BACK', '전량 조회의 상한을 넘었다. 조용히 자르면 전량 이 거짓말이 된다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.query.unknown-field', 'BACK', '화이트리스트에 없는 필드로 조건이 왔다. 스펙에 .col(…) 이 없다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.query.value', 'BACK', '값의 형태가 연산자와 맞지 않는다 — between 이 2원소가 아니거나 해석 불가.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.reset.code-expired', 'BACK', '만료 · 이미 사용 · 시도 한도 초과 — 셋이 한 문구다. 사용자가 할 일이 셋 다 같기 때문이다(①로 돌아가 다시 받는다). 갈라 두면 "이 아이디에 유효한 토큰이 있었다" 를 알려주는 응답이 생긴다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.reset.code-invalid', 'BACK', '인증번호가 맞지 않다. 남은 시도 횟수를 알려주지 않는다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.role.auth.action', 'BACK', '그 메뉴에 정의되지 않은 액션이다 — screen/admin/system/user/requirements.md 의 —. 줄 것이 없는 조합이다. 받아 두면 인가 데이터가 줬는데 안 되는 상태를 갖게 되고, 그 다음 문의는 "권한을 줬는데 왜 안 되나" 가 된다. EXPORT 는 API 가 없어도 정의될 수 있으므로(sys/menu.md) 이유를 API 의 부재로 대지 않는다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.role.auth.menu', 'BACK', '구조 노드나 없는 메뉴에 권한을 주려 했다 — sys/menu.md 의 MENU_URL IS NULL 거부. 화면에는 구조 노드에 스위치가 아예 없다(screen/menu/requirements.md). 이 문구가 나가는 것은 화면 밖 경로이거나, 트리를 열어 둔 사이에 그 메뉴가 폴더가 된 경우다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.role.auth.read', 'BACK', 'READ 없이 다른 액션만 왔다 — screen/admin/system/user/requirements.md 의 불변식 하나. 화면이 이것을 유지하므로(끄면 함께 끄고, 켜면 함께 켠다) 정상 경로로는 오지 않는다. 서버가 다시 보는 것은 sys/menu.md 의 원칙 P1 이며 MENU_URL IS NULL 거부와 같은 자리다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.role.duplicate', 'BACK', 'ROLE_ID 중복 — 다른 사람이 방금 만든 것을 클라이언트가 알 수 없다(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.role.name-required', 'BACK', '역할명을 비운 채 저장했다 — screen/menu/requirements.md 의 필수 컬럼.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.role.not-deletable', 'BACK', '삭제 게이트 — 보유 사용자나 권한 행이 남아 있다(screen/menu/requirements.md). 거의 항상 삭제가 아니라 USE_YN=''N'' 이다. 이 게이트를 통과하는 역할은 한 번도 쓰이지 않은 것뿐이며 그것이 정확히 잘못 만든 역할 이다 — 쓰인 역할을 지우면 누가 무슨 역할을 가졌었나 가 사라진다(sys/menu.md). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.role.not-found', 'BACK', '없는 역할을 가리켰다. 화면이 낡았거나 화면 밖 경로다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.searchCond.limit', 'BACK', '한 화면에 저장할 수 있는 조회조건 수를 넘겼다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.session.evicted', 'BACK', '다른 곳의 로그인에 밀려 이 세션이 끝났다 — 유휴 만료와 뜻이 다르다(backend/security.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.unauthenticated', 'BACK', '세션이 없거나 만료됐다. 프론트가 로그인 화면으로 돌린다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.unclassified-api', 'BACK', '세 계층 프리픽스 밖의 /api/** — 경로 차원의 fail-closed.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-admin.duplicate', 'BACK', 'USER_ID 중복 — 다른 사람이 방금 만든 것을 클라이언트가 알 수 없다(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-admin.email-required', 'BACK', '이메일을 비운 채 저장했다 — screen/admin/system/user/requirements.md 의 필수 컬럼. 필수인 이유가 발송처다. 관리자가 발급한 임시 비밀번호를 전할 곳이 없으면 그 계정은 만들어지자마자 들어올 수 없다(AUTH-07). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-admin.name-required', 'BACK', '이름을 비운 채 저장했다 — screen/admin/system/user/requirements.md 의 필수 컬럼.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-admin.no-delete', 'BACK', '삭제 행이 왔다 — SYS_USER 는 물리 삭제를 하지 않는다(sys/user-role.md · USER-02). 화면에는 삭제 컬럼이 아예 없다(screen/admin/system/user/requirements.md). 못 쓰게 하는 수단은 USE_YN=''N'' 이며 그것은 셀 편집이다 — 이력 테이블이 USER_ID 를 값으로 갖고 있어(sys/user-role.md) 행을 지우면 지난 이력의 주인이 사라진다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-admin.not-found', 'BACK', '없는 계정을 가리켰다. 화면이 낡았거나 화면 밖 경로다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-admin.period', 'BACK', '사용 기간의 시작이 종료보다 늦다 — 그 계정은 어느 날도 쓸 수 없다(sys/INDEX.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-admin.reset-disabled', 'BACK', '임시 비밀번호 발급이 꺼져 있다 — sys-config.auth.password.admin-reset-enabled. 기본값이 켜짐인 것이 결정이다(sys/code.md) — 메일 연동이 없는 배포에서 잠긴 계정을 푸는 유일한 경로이며, 끄면 복구 수단이 사라진다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-admin.self-disable', 'BACK', '자기 계정을 비활성화하려 했다 — screen/admin/system/user/requirements.md. 권한이 아니라 대상 제약이라 화면은 감추지 않고 보이되 막고 사유를 붙인다(frontend/tabs.md 의 예외가 아니라 축이 다른 것이다). 그 자리에서 화면 밖으로 밀려나기 때문이며, 되돌릴 사람이 그 사람 자신이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-auth.action', 'BACK', '그 메뉴에 정의되지 않은 액션이다 — screen/admin/system/user/requirements.md 의 —. 줄 것이 없는 조합이다. 받아 두면 줬는데 안 되는 상태가 인가 데이터에 남고, 그 다음 문의는 "권한을 줬는데 왜 안 되나" 가 된다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-auth.duplicate', 'BACK', '같은 (메뉴, 액션) 이 두 번 왔거나 이미 있는 행을 새로 만들려 했다. PK 가 (USER_ID, MENU_CD, ACTION_CD) 이므로 한 조합에 행은 하나뿐이며, 재부여는 새 행이 아니라 같은 행의 기간·사유를 갱신하는 것이다(screen/admin/system/user/requirements.md). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-auth.menu', 'BACK', '구조 노드나 없는 메뉴에 예외를 주려 했다 — sys/menu.md 의 MENU_URL IS NULL 거부. 화면에는 구조 노드에 스위치가 아예 없다(screen/admin/system/user/requirements.md). 이 문구가 나가는 것은 화면 밖 경로이거나, 트리를 열어 둔 사이에 그 메뉴가 폴더가 된 경우다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-auth.missing', 'BACK', '고치거나 지우려는 행이 없다 — 다른 사람이 먼저 지웠다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-auth.not-found', 'BACK', '없는 계정에 예외를 주려 했다. 화면이 낡았거나 화면 밖 경로다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-auth.period', 'BACK', '시작이 종료보다 늦다 — 그 예외는 어느 날도 유효하지 않다(sys/INDEX.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-auth.period-required', 'BACK', '기간을 비운 채 저장했다 — 개인 예외에는 무기한이라는 선택지가 없다(sys/menu.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-auth.read', 'BACK', 'READ 없이 다른 액션만 남는다 — screen/admin/system/user/requirements.md 의 불변식 하나. 역할 쪽과 판정이 다르다. 거기서는 그 역할 안에서만 봤지만 여기서는 유효 권한이 역할과 개인 예외의 합집합이므로(backend/security.md ③), 역할이 조회를 주고 있으면 개인 예외에는 저장만 있어도 된다 — 실제로 그것이 이 화면의 흔한 쓰임이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-auth.reason-required', 'BACK', '사유를 비운 채 저장했다 — 필수다(AUTHZ-07). 변경 이력 테이블을 두지 않았으므로(sys/logs.md) "누구에게 왜 무엇을 언제까지 줬는가" 를 남기는 것이 이 컬럼뿐이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-detail.ip', 'BACK', 'IP 도 CIDR 도 아니다 — sys/user-role.md 이 DDL 에 두지 않은 검사다. 벤더 중립 DDL 에 정규식 CHECK 를 둘 수 없고(backend/persistence.md), 둘 수 있어도 IPv6 축약까지 정규식으로 맞추는 것은 저장 시 파싱보다 약하다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-detail.ip-duplicate', 'BACK', '같은 대역을 두 번 넣었다 — PK 가 (USER_ID, IP_CIDR) 다(sys/user-role.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-detail.ip-missing', 'BACK', '고치거나 지우려는 대역이 없다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-detail.period', 'BACK', '부여 기간의 시작이 종료보다 늦다 — 그 부여는 어느 날도 유효하지 않다(sys/INDEX.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-detail.role', 'BACK', '없는 역할을 줬다 — 화면이 낡았거나 화면 밖 경로다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-detail.role-duplicate', 'BACK', '이미 가진 역할을 또 줬다 — PK 가 (USER_ID, ROLE_ID) 다(sys/menu.md). 재부여는 같은 행의 기간을 갱신하는 것이지 새 행이 아니다. 만료된 부여가 목록에 남아 있는데 다시 주려고 행을 추가하면 이 오류가 나며, 할 일은 그 행의 종료일을 미는 것이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-detail.role-missing', 'BACK', '고치거나 지우려는 부여가 없다 — 다른 사람이 먼저 정리했다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-detail.user', 'BACK', '없는 계정에 무언가를 매달려 했다 — FK 가 막기 전에 우리가 먼저 말한다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-session.index', 'BACK', '세션 인덱스가 없어 활성 세션을 나열할 수 없다 — backend/session.md · backend/security.md. 빈 목록으로 답하지 않는다. 그러면 "이 사람은 지금 아무 데도 안 들어와 있다" 로 읽히는데 그것은 모르는 것을 아는 것처럼 말하는 것이다 — 이 탭이 하는 일이 끊을까 말까 이므로 그 거짓말의 대가가 크다. 스토어가 있는데 인덱스가 없는 배포는 SecurityConfig 가 기동에서 막으므로, 여기 닿는 것은 store-type: none 하나이며 그것은 선택된 동작이다(단일 노드 · 개발). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user-session.self', 'BACK', '자기 세션을 끊으려 했다 — screen/admin/system/user/requirements.md. 그 자리에서 화면 밖으로 밀려난다. 사용 여부 ''N'' 전환과 같은 이유로 막고 다른 자리에서 막는다: 저것은 셀 편집이라 컬럼이 막고, 이것은 실행이라 버튼이 비활성이며 서버가 다시 본다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user.locale-unsupported', 'BACK', '지원하지 않는 언어를 고르려 했다. 화면은 목록만 보여주지만 판정은 서버다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user.pwd-mismatch', 'BACK', '현재 비밀번호가 다르다. 새 비밀번호 쪽 문제와 갈라야 한다 — 합치면 무엇을 고칠지 모른다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user.pwd-reused', 'BACK', '최근 N건 안에 있던 비밀번호다 — 건수는 정책이 정한다(sys/user-role.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user.pwd-unchanged', 'BACK', '지금 쓰는 것과 같다. 재사용 이력에는 아직 없으므로 별도 판정이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.user.pwd-weak', 'BACK', '새 비밀번호가 정책의 최소 길이·문자 종류를 못 채웠다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('err.validation', 'BACK', '요청 값 검증 실패. 필드별 오류가 함께 나간다(backend/api.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.anonymous', 'FRONT', '사용자 컬럼이 빈 행의 표시 — 빈칸은 *수집이 안 된 것*과 구분되지 않는다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.col.clientIp', 'FRONT', 'IP 컬럼 — 기본 숨김이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.col.creDtm', 'FRONT', '일시 컬럼 — 정렬이 열린 유일한 컬럼이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.col.detail', 'FRONT', '상세 컬럼 — 파생이며 셀에 그려지는 것은 `[보기]` 다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.col.errCd', 'FRONT', '오류 코드 컬럼 — 문자열 상수라 이 값으로 묶어 센다(backend/packages.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.col.errMsg', 'FRONT', '메시지 컬럼 — 서버가 완성한 문장이며 사용자가 그때 본 그 글이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('settings.grid.rowHeight', 'FRONT', '그리드 행 높이.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.col.httpStat', 'FRONT', '상태 컬럼 — 4xx 와 5xx 를 가른다. 배지의 색이 그 둘이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.col.menu', 'FRONT', '메뉴 컬럼 — 요청 URI 앞에 보인다(2026-09-01. 그 전에는 기본 숨김이었다). 클라이언트 주장이라 헤더 툴팁이 그 사실을 말한다(backend/packages.md). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.col.requestUri', 'FRONT', '요청 URI 컬럼 — 더블 클릭이 `API_CATALOG` 로 건너뛴다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.col.seq', 'FRONT', '순번 컬럼 — tie-breaker 이며 기본 숨김이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.col.traceId', 'FRONT', '추적 ID 컬럼 — 5xx 토스트의 그 값이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.col.userId', 'FRONT', '사용자 아이디 컬럼 — 미인증 요청은 #ERROR_LOG_ANONYMOUS 다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.col.userNm', 'FRONT', '사용자명 컬럼 — `SYS_USER` 를 조인해 얻는다(2026-09-01). 미인증 요청과 지워진 계정에서 빈다 — 왼쪽 칸이 이미 `(익명)` 이라고 말하므로 그 자리를 채우지 않는다(사용 이력과 같은 규칙이다). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.detail.length', 'FRONT', '모달 하단의 글자 수 — `{count}`.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.detail.link', 'FRONT', '상세 셀에 그려지는 글자 — 값이 아니라 여는 것이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.detail.title', 'FRONT', '상세 모달의 제목.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.detail.truncated', 'FRONT', '상한에서 잘렸다 — 말하지 않으면 잘린 값을 깨진 값으로 읽는다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.empty', 'FRONT', '0건일 때 — 보존 기간(180일)을 함께 말한다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.empty.server', 'FRONT', '5xx 만 으로 물었는데 0건이다 — 진단으로 읽히게 한다(screen/admin/system/log/access/requirements.md). *"조회 결과가 없습니다"* 로 끝내면 답이 빈 결과로 읽힌다. 이 기간에 서버 오류가 없었다는 것은 가장 듣고 싶은 답이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.empty.trace', 'FRONT', '추적 ID 로 물었는데 0건이다 — 유실이 아니다(screen/admin/system/log/access/requirements.md). §1.4 이후 모든 요청은 사용 이력에 있고 여기는 예외가 난 것만 받는다. 그래서 0건이면 *"그 요청은 오류가 아니었다"* 는 뜻이며 사용 이력에는 반드시 있다 — 문구가 그 사실을 사용자 말로 옮겨 사용 이력으로 보낸다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.footer.range', 'FRONT', '푸터 왼쪽의 덧붙임 — `{days}`. 총 건수를 잃은 자리를 메운다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.grid.title', 'FRONT', '마스터 그리드의 제목 — 이 화면에 그리드가 하나다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.menu.clientClaim', 'FRONT', '메뉴 헤더의 툴팁 — 클라이언트 주장이다(backend/packages.md · backend/security.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.noMenu', 'FRONT', '메뉴 컬럼이 빈 행의 표시 — 로그인·하트비트는 셸 진입 전이라 메뉴가 없다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.payload.none', 'FRONT', '전문 탭이 비어 있는데 파기는 아니다 — 멀티파트 요청·캐싱이 꺼진 구간이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.payload.purged', 'FRONT', '전문 탭이 비어 있는 이유 — 사용 이력 90일이 지났다(screen/admin/system/log/access/requirements.md). §3.7 의 *"이미 파기된 이력입니다"* 와 같은 어휘다. 보존이 180일 / 90일로 달라 생기는 일이며 고장이 아니다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.search.errCd', 'FRONT', '조회조건 — 오류 코드. 완전 일치다. 셀을 복사해 넣는 동선이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.search.menu', 'FRONT', '', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.search.menuCd', 'FRONT', '조회조건 — 메뉴 코드. 문의 전화가 주는 것이 시각과 화면 이름이다(screen/admin/system/log/access/requirements.md). 이름을 받는 칸이 아래에 따로 있으므로 이 칸은 코드를 아는 사람의 것이다 — 대개 개발자이며, 오류 코드 칸과 같은 동선(셀을 복사해 넣는다)이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.search.menuNm', 'FRONT', '조회조건 — 메뉴명. 이름은 `SYS_MESSAGE` 에 있어 서버가 `EXISTS` 로 푼다(sys/code.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.search.period', 'FRONT', '조회조건 — 기간. 필수이며 상한은 시스템 값(92일) 그대로다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.search.requestUri', 'FRONT', '조회조건 — 요청 URI. 앞 일치다(인덱스가 없다).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.search.status', 'FRONT', '조회조건 — 상태. 파생이며 묶음 둘이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.search.traceId', 'FRONT', '조회조건 — 추적 ID. 넣으면 기간이 선택이 된다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.search.userId', 'FRONT', '조회조건 — 사용자 아이디. 문자열 비교 넷이다 — 기간이 먼저 좁힌다(2026-09-01).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.search.userNm', 'FRONT', '조회조건 — 사용자명. 이름은 `SYS_USER` 조인이 답한다(2026-09-01).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.stack.none', 'FRONT', '스택 탭이 비어 있는 이유 — 4xx 라 저장하지 않았다(screen/admin/system/log/access/requirements.md). *"없습니다"* 로 끝내지 않는다. 인가 거부의 스택은 인터셉터 프레임뿐이고 전 행이 같아서 일부러 저장하지 않은 것이며, 그것을 말하지 않으면 유실로 읽는다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.status.client', 'FRONT', '상태 묶음의 항목 — 403 이 대부분이며 대개 정상 동작이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.status.server', 'FRONT', '상태 묶음의 항목 — 이 화면의 가장 흔한 조회다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.tab.payload', 'FRONT', '탭 하나 — 요청 전문. 다른 테이블에서 온다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('errorLog.tab.stack', 'FRONT', '탭 하나 — 스택트레이스. 4xx 는 비활성이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('excel.upload.ambiguousCode', 'FRONT', '코드명이 두 코드에 걸린다 — `{value}`(playbook/INDEX.md). 둘 중 하나를 조용히 고르지 않는다 — 그렇게 저장된 행은 화면에서 정상으로 보인다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('excel.upload.duplicated', 'FRONT', '파일 안에서 키가 겹쳤다 — 어느 칸이라 말할 수 없다(키 조합이다).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('excel.upload.headerMismatch', 'FRONT', '양식이 다르다 — `{expected}` · `{actual}`. 읽지 않는다(playbook/INDEX.md). 어긋난 채로 읽으면 열이 하나 밀려 수량 자리에 단가가 들어가고, 그 파일은 저장까지 통과한다. /', NULL, NULL, NULL, NULL);
