INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.filter.clear', 'FRONT', '날짜 필터를 푸는 버튼. 칸마다 있는 × 로도 지워지지만 두 번 눌러야 한다. 필터를 푸는 것은 거는 것보다 급한 동작이다 — 걸어 둔 것을 잊고 조회하면 0건이 데이터가 없는 것으로 읽힌다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.filter.empty', 'FRONT', '로드된 행에 값이 하나도 없을 때 — 목록이 비면 고장으로 보인다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.filter.from', 'FRONT', '날짜 필터의 시작 칸 — frontend/grid.md · playbook/INDEX.md. 플레이스홀더이지 라벨이 아니다. 칸이 둘뿐이라 시작·끝 이라는 글자가 밖에 또 서면 폭의 절반을 먹는데, 헤더 팝업은 컬럼 폭에 매여 있어 그럴 자리가 없다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.filter.to', 'FRONT', '〃 끝 칸. 비워 두면 위쪽이 열린다 — 단측이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.footer.count', 'FRONT', '페이징이 없는 그리드(`mode: ''all''`)의 푸터 — `{count}`.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.footer.filtered', 'FRONT', '컬럼 필터가 걸렸을 때 덧붙는 문구 — `{loaded}` · `{shown}`(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.footer.loaded', 'FRONT', '커서형 푸터의 왼쪽 — `{count}`(screen/admin/system/log/access/requirements.md). `GRID_FOOTER_TOTAL` 과 다른 말이다. 저것은 전부가 몇 건이고 이것은 이 장이 몇 건이다 — 총 건수를 세지 않기로 한 화면에서 총 이라고 쓰면 거짓말이 된다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.footer.pageSize', 'FRONT', '', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.footer.total', 'FRONT', '푸터 왼쪽 — `{total}` · `{pages}`.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.issue.column', 'FRONT', '저장 실패 표의 머리 셋 — `컬럼` · `값` · `사유`(frontend/grid.md ④). 행 번호 칸이 없다. 판에 클라이언트 정렬이 걸리면 우리가 센 배열 순서와 화면의 번호가 어긋나고, *틀린 번호는 없는 번호보다 나쁘다*. 어느 줄인지는 붉은 셀이 말하고 판이 첫 실패로 데려간다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.issue.excel', 'FRONT', '그 표 아래의 실패분 내려받기 — backend/row-transaction.md §7. 표는 읽을 수는 있어도 고쳐서 다시 낼 수는 없다. 오백 행을 올려 열둘이 걸린 자리에서 남는 일은 화면에서 원본 파일로 옮겨 적는 것이며, 그것이 이 버튼이 없앤다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.issue.excel.file', 'FRONT', '그 파일 이름의 가운데 토막 — 메뉴 코드와 시각 사이에 들어간다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.issue.excel.sheet', 'FRONT', '그 파일의 둘째 시트 이름. 사유가 둘째 시트인 것이 결정이다 — 첫 시트에 열로 붙이면 양식이 달라져 다시 올릴 수 없다(readWorkbook 이 뒤에 붙은 열까지 세어 막는다). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.issue.reason', 'FRONT', '그 표의 사유 칸. 서버가 완성한 문구를 그대로 싣는다(backend/packages.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.issue.row', 'FRONT', '그 시트의 첫 머리 — 첫 시트의 몇 번째 데이터 줄인가.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.issue.value', 'FRONT', '그 표의 값 칸 — *무엇이* 중복인가에 답하는 자리다(frontend/grid.md ④).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.list.add', 'FRONT', '항목을 고르는 팝업을 연다 — 여기서 타이핑을 받지 않는다(목록에 없는 값이 생긴다).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.list.down', 'FRONT', '〃 아래로.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.list.empty', 'FRONT', '항목이 하나도 없을 때 — 비었다고 말한다. 빈 창을 그냥 두면 아직 안 불러온 것과 구별되지 않는다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.list.remove', 'FRONT', '항목 하나를 뺀다. 배열 전체를 비우는 버튼이 아니다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.list.up', 'FRONT', '항목을 한 칸 위로 — 순서가 값의 일부다(playbook/INDEX.md 의 `SORT_NO`). 아이콘만 있는 버튼이라 툴팁이 유일한 설명이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.page.jumpNext', 'FRONT', '다섯 쪽 뒤로 — 판의 점 셋이 그 뜻이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.page.jumpPrev', 'FRONT', '다섯 쪽 앞으로 — 판의 점 셋이 그 뜻이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.page.next', 'FRONT', '한 쪽 뒤로.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.page.prev', 'FRONT', '페이지 이동 — 한 쪽 앞으로.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.partial.gone', 'FRONT', '곧 다시 읽는다고 미리 알린다 — after: ''reload'' 전용. 닫는 순간 이 표가 사라진다. 재조회가 목록을 갈아 끼우므로 어느 넷이 왜 안 됐나 를 다시 볼 방법이 없고, 남는 것은 내려받아 둔 파일뿐이다. 그래서 닫기 전에 말한다. 사후 통보이면 사용자가 아무 일도 하지 못한다 — 이미 사라진 뒤이며, 그 안내는 알림이 아니라 부고 다. #GRID_PARTIAL_KEPT 와 함께 뜨지 않는다. 앞은 *목록을 비웠다* 이고 여기는 *목록을 새로 읽는다* 라 서로를 부정한다 — 뒤처리가 둘 중 하나뿐이므로 문구도 하나만 선다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.partial.kept', 'FRONT', '목록을 비웠다고 알린다 — `{count}` · `{failed}`. after: ''keepFailed'' 전용. 말하지 않으면 사라진 것으로 보인다. 500건을 저장했는데 화면에 12줄만 남으면 사용자는 488건도 실패했나 를 먼저 의심한다 — 남은 것이 고칠 것이라는 사실은 배관만 알고 있으므로 배관이 말해야 한다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.partial.summary', 'FRONT', '그 요약 — `{total}` · `{done}` · `{failed}`. 건수가 먼저다: 표는 그 뒤의 상세다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.partial.title', 'FRONT', '건별 처리의 결과 제목 — backend/row-transaction.md. 성공도 실패도 아닌 이름이어야 한다. 488건이 저장되고 12건이 안 된 일은 둘 중 어느 쪽도 아니며, 어느 한쪽으로 부르면 화면이 거짓말을 한다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.pk.locked', 'FRONT', '저장된 행의 PK 칸을 고치려 했을 때 — frontend/grid.md 의 `pk`. *"고치려면 지우고 다시 만든다"* 가 답인데 그것은 화면 어디에도 적혀 있지 않다 — 잠긴 칸은 왜 잠겼는지를 말하지 않으면 버그로 읽힌다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.read', 'FRONT', '그리드 헤더 ①의 조회 버튼.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.read.empty', 'FRONT', '조회 결과가 0건일 때의 알림 — 마스터만 기본으로 켠다(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.revert', 'FRONT', '상태 컬럼의 되돌리기 아이콘 — 수정한 행을 원본으로 돌린다(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.save', 'FRONT', '그리드 헤더 ①의 저장 버튼.', NULL, NULL, NULL, NULL);
