INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.save.confirm.hidden', 'FRONT', '컬럼 필터로 보이지 않는 변경 행이 있을 때 덧붙는다 — `{hidden}`(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.save.confirm.title', 'FRONT', '저장 전 확인의 제목.', NULL, NULL, NULL, NULL);
