INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.save.nothing', 'FRONT', '저장할 변경이 없는데 저장을 눌렀을 때.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.save.warn.title', 'FRONT', '건수 확인 앞에 서는 경고의 제목 — screen/admin/system/code/requirements.md. 본문은 화면이 만든다. 건수는 얼마나를 말할 뿐이라 무엇이 일어나는지 를 말하지 못하며, 그것을 아는 것은 화면이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.selectAll', 'FRONT', '다중 선택 컬럼 헤더의 전체 선택 체크박스 이름.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.selectRow', 'FRONT', '다중 선택 컬럼에서 행 하나를 고르는 체크박스 이름.', NULL, NULL, NULL, NULL);
