INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.settings.apply', 'FRONT', '적용 버튼 — 고친 것을 화면에만 두고 닫는다. DB 에는 남기지 않는다(frontend/grid.md).', NULL, NULL, NULL, NULL);
