INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.settings.drag', 'FRONT', '순서를 바꾸는 손잡이 — 아이콘만 보이며 읽는 것은 스크린리더다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.settings.noneVisible', 'FRONT', '컬럼을 전부 끄고 저장하려 했을 때 — 빈 그리드가 되면 되돌릴 컨트롤이 그 안에 있다.', NULL, NULL, NULL, NULL);
