INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.settings.reset', 'FRONT', '초기화 버튼 — 저장된 설정을 지우고 화면 선언으로 돌아간다.', NULL, NULL, NULL, NULL);
