INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.split.collapseFirst', 'FRONT', '스플리터의 위 화살표 — 막대를 맨 위로 보내 위 그리드를 접는다(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.split.collapseSecond', 'FRONT', '스플리터의 아래 화살표 — 막대를 맨 아래로 보내 아래 그리드를 접는다(frontend/grid.md).', NULL, NULL, NULL, NULL);
