INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.validation.count', 'FRONT', '검증 실패 건수 — `{count}`(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('grid.validation.line', 'FRONT', '검증 실패 한 줄 — `{column}` · `{message}`(frontend/grid.md ④의 *목록*). 건수만으로는 **무엇이 틀렸는지** 알 수 없다. 붉은 셀이 *어디* 를 말하고 이 줄이 *무엇* 을 말한다 — 컬럼 이름을 앞에 붙이는 것은 같은 문구가 여러 컬럼에서 날 수 있기 때문이다(`필수 항목입니다`). /', NULL, NULL, NULL, NULL);
