INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('login.lockedReset', 'FRONT', '잠김·휴면 안내 배너 **안에** 붙는 재설정 링크(screen/_standalone/README.md · login 요건서 §6-4). 폼 아래의 평소 링크와 문구가 다른 것이 의도다 — 저것은 *어쩌다 잊은 사람* 에게 하는 말이고 이것은 **지금 막힌 사람**에게 하는 말이다. /', NULL, NULL, NULL, NULL);
