INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.col.userAgent', 'FRONT', 'User-Agent 컬럼 — 기본 숨김이다. 켜면 다른 컬럼이 전부 밀린다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.col.userId', 'FRONT', '사용자 아이디 컬럼 — 시도한 ID 다(screen/admin/system/log/access/requirements.md). 헤더가 *시도 ID* 였다(2026-09-01 에 바뀌었다). 이력 셋의 헤더를 사용자 아이디 · 사용자명으로 통일하면서 갈렸는데, *사용자* 라고 쓰면 `SYS_USER` 에 있는 것처럼 읽힌다던 걱정은 이름 칸의 `없는 계정` 배지가 대신 말한다 — 헤더를 화면마다 다르게 부르는 대가가 더 크다. 툴팁(#LOGIN_LOG_USER_ID_ATTEMPTED)은 남는다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.col.userNm', 'FRONT', '사용자명 컬럼 — `SYS_USER` 를 조인해 얻는다(2026-09-01). 없는 계정의 시도에서는 비고, 그 자리에 `없는 계정` 배지가 붙는다. 배지의 글자와 색은 결과 컬럼의 `FAIL_NO_USER` 와 같은 것이며 같은 공통코드 행 (`code.LOGIN_RSLT_CD.FAIL_NO_USER`)에서 온다 — 한 행의 두 칸이 같은 사실을 두 글자로 말하면 사람이 둘을 다른 사실로 읽는다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.empty', 'FRONT', '0건일 때 — 보존 기간(1년)을 함께 말한다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.empty.failed', 'FRONT', '실패만 으로 물었는데 0건이다 — 문구가 다르다(screen/admin/system/log/access/requirements.md). *"조회 결과가 없습니다"* 로 끝내면 진단이 빈 결과로 읽힌다. 이 기간에 로그인 실패가 없었다는 것은 답이지 실패가 아니다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.footer.range', 'FRONT', '푸터 왼쪽의 덧붙임 — `{days}`. 총 건수를 잃은 자리를 메운다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.grid.title', 'FRONT', '마스터 그리드의 제목 — 이 화면에 그리드가 하나다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.noUserId', 'FRONT', '시도 ID 가 빈 행의 표시 — 빈칸은 *수집이 안 된 것*과 구분되지 않는다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.rsltGroup.closed', 'FRONT', '결과 묶음의 항목 — 로그아웃·만료·강제·밀려남 넷.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.rsltGroup.failed', 'FRONT', '결과 묶음의 항목 — `FAIL_*` 열. 이 화면의 기본 동선이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.search.clientIp', 'FRONT', '조회조건 — IP. 완전 일치다. 실패 행에서 복사해 다시 조회하는 동선이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.search.period', 'FRONT', '조회조건 — 기간. 필수이며 상한은 시스템 값(92일) 그대로다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.search.result', 'FRONT', '조회조건 — 결과. 다중 선택이며 후보는 공통코드가 낸다(sys/code.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.search.rsltGroup', 'FRONT', '조회조건 — 결과 묶음. 파생이며 배지의 색 셋과 같은 축이다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.search.traceId', 'FRONT', '조회조건 — 추적 ID. 넣으면 기간이 선택이 된다(screen/admin/system/log/access/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.search.userId', 'FRONT', '조회조건 — 사용자 아이디. 문자열 비교 넷(같음 · 시작 · 포함 · 끝)이다(2026-09-01). 인덱스가 없는 것은 그대로인데 기간이 먼저 좁힌다(screen/admin/system/log/access/requirements.md). IP 를 완전 일치로 둔 것과 갈리는 자리다 — 대역 검색은 결과만 넓어지는 조건이지만, 부분 아이디는 다른 답을 낸다(`admin` 으로 끝나는 시도가 그렇다). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.search.userNm', 'FRONT', '조회조건 — 사용자명. 없는 계정의 시도는 이름이 없어 이 조건에 걸리지 않는다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('loginLog.userId.attempted', 'FRONT', '시도 ID 헤더의 툴팁 — 등록된 계정이 아닐 수 있다(sys/logs.md · screen/admin/system/log/access/requirements.md). 말하지 않으면 없는 ID 의 행이 결함처럼 보인다. 그 행들이야말로 이 화면의 두 번째 용도(침입 시도 탐지)가 찾는 것이다. /', NULL, NULL, NULL, NULL);
