INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('menuTree.col.roleId', 'FRONT', '탭 3 — 역할 ID 컬럼. 메뉴 쪽 라벨을 돌려쓰지 않는다. 한때 MENU_COL_MENU_CD 를 그대로 썼는데 헤더가 메뉴 코드 인 칸에 역할 ID 가 들어가 있었다(2026-08-30 실물) — 같은 화면 안에서 컬럼 폭과 자리가 맞으면 틀린 라벨이 눈에 띄지 않는다. /', NULL, NULL, NULL, NULL);
