INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('profile.version', 'NONE', '모달 하단의 버전·환경 — `{version}` · `{env}`. 푸터를 없애며 여기로 옮긴 것이다(51 §2).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('progress.background', 'FRONT', '창을 닫아도 계속된다 — playbook/INDEX.md 의 모달은 닫을 수 있고 작업은 계속 돈다. 말하지 않으면 사용자는 닫으면 취소되는 것으로 읽고 끝날 때까지 앉아 있는다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('progress.count', 'FRONT', '처리한 건수와 완료율 — `{cur}` / `{tot}` / `{percent}`. **전체를 모르면 아래 PROGRESS_COUNT_UNKNOWN 이 대신 온다**(sys/batch.md) — 그때는 나눌 수가 없어 퍼센트가 아예 없다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('progress.count.unknown', 'FRONT', '**전체를 모르는 작업의 건수** — `{cur}` 뿐이다(sys/batch.md). 이 줄이 없으면 그 작업의 창에는 도는 막대만 남고, 그것은 멈춘 것과 구별되지 않는다 — 건수라도 올라가는 것이 돌고 있다는 유일한 증거다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('progress.done', 'FRONT', '접힌 채 끝났다 — `{title}` 은 그 실행의 이름이다. 창이 열려 있었으면 100% 막대가 그 말을 한다. 접혀 있으면 표시가 사라지는 것 말고는 끝났다는 신호가 없어, 사용자는 내가 놓쳤나 를 묻는다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('progress.elapsed', 'FRONT', '**창이 뜬 지 얼마나 지났는가** — `{min}` 분 `{sec}` 초. 퍼센트만으로는 기다릴 수 없다. 사용자가 이 창 앞에서 하는 결정은 기다릴까 접을까 하나이며, 3초 지난 24% 와 5분 지난 24% 는 그 결정이 정반대다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('progress.failed', 'FRONT', '작업이 실패했다. 사유는 서버가 준 `ERR_MSG` 가 아래 붙는다. 아래 PROGRESS_UNREACHABLE 과 갈라야 하는 문구다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('progress.reopen', 'FRONT', '접힌 표시를 누르면 창이 돌아온다 — playbook/INDEX.md. 표시에는 그 실행의 이름이 이미 적혀 있다. 이 문구는 그것이 눌린다는 사실을 말하며 — 진행 중 표시는 흔히 보여 주기만 하는 것이라, 누를 수 있다는 것을 말하지 않으면 사용자는 다시 실행으로 창을 되찾으려 한다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('progress.unreachable', 'FRONT', '진행률을 볼 수 없다 — 작업이 실패한 것이 아니다. 폴링이 연속으로 실패한 경우이며 작업은 여전히 돌고 있을 수 있다. 이것을 실패로 말하면 사용자는 다시 실행하고, 그때 같은 작업이 두 번 돈다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('pwd.rule.charset-kinds', 'BACK', '문자 종류 수 규칙 — {kinds}.', NULL, NULL, NULL, NULL);
