INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('screenTabs.dirty.content', 'FRONT', '미저장인 채로 다른 모드로 옮기려 할 때의 본문. 탭 닫기 문구를 쓰지 않는다. 저기는 *닫으면 잃는다* 인데 여기서는 화면이 남아 있다 — 같은 말을 쓰면 사용자는 탭이 닫히는 줄 알고 멈춘다. 잃는 것은 같으므로 제목은 함께 쓴다. /', NULL, NULL, NULL, NULL);
