INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.session.title', 'FRONT', '탭 4 의 제목.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('search.op.gt', 'FRONT', '연산자 셀렉터 — 초과(`>`). 크기 계열의 넷째 실물이다(playbook/INDEX.md). 이상과 한 글자 차이라 글자가 일해야 한다. 기호(`>`)는 `≥` 와 밑줄 하나 차이이고 좁은 칸에서는 그 차이가 안 보인다 — 이름이 초과 라고 말해야 사람이 경계값이 들어가는지를 안다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('search.op.gte', 'FRONT', '연산자 셀렉터 — 이상(`>=`). 크기 계열의 둘째 실물이다(frontend/search-form.md). screen/admin/system/batch/schedule/requirements.md 의 *소요 시간 이상* 이 처음 요구했다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('search.op.in', 'FRONT', '연산자 셀렉터 — 여럿 중 하나. 고르면 콤보가 다중 선택이 된다(`부분 일치` 와 다르다).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('search.op.isNotNull', 'FRONT', '연산자 셀렉터 — 값 있음. `in` 으로 표현할 방법이 아예 없는 조건이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('search.op.isNull', 'FRONT', '연산자 셀렉터 — 값 없음. 고르면 값 칸이 사라진다(backend/api.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('search.op.lt', 'FRONT', '연산자 셀렉터 — 미만(`<`). 크기 계열의 다섯째이자 마지막이다(playbook/INDEX.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('search.op.lte', 'FRONT', '연산자 셀렉터 — 이하(`<=`). 크기 계열의 셋째 실물이다(frontend/search-form.md). screen/admin/system/user/requirements.md 의 기간 칸 둘이 처음 요구했다(2026-08-31). *한쪽만 아는 조건* 이 실제로 있다 — 이 날짜 이후로 한 번도 안 들어온 계정 이 `lte` 이고 그 반대가 `gte` 다. /', NULL, NULL, NULL, NULL);
