INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.col.validToDt', 'FRONT', '컬럼 — 사용 기간 종료.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.detail.empty', 'FRONT', '아직 아무도 고르지 않았다 — *"사용자를 선택하세요"*(frontend/grid.md). **비활성되는 것은 버튼이지 탭이 아니다**(screen/admin/system/user/requirements.md). 탭은 열리되 비어 있고 안내가 뜬다 — 탭을 잠그면 *"이 사용자에게 역할 탭이 없나"* 로 읽힌다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.detail.locked', 'FRONT', '미저장 신규 행을 골랐다 — *"저장 후 편집할 수 있습니다"*(frontend/grid.md). `SYS_USER_ROLE` 이 `SYS_USER` 를 FK 로 참조하므로(sys/user-role.md) **부모가 저장되기 전에는 자식을 만들 수 없다.** 빈 상태와 **같은 빈 판이지만 다음에 할 일이 다르다**. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.duplicate', 'FRONT', '같은 그리드 안에 같은 로그인 ID 가 둘이다 — 화면이 판정할 수 있는 중복이다(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.eff.col.grantRsn', 'FRONT', '컬럼 — 사유. 개인 예외 경유일 때만 있다(역할 부여에는 사유가 없다 — sys/menu.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.eff.col.menu', 'FRONT', '컬럼 — 메뉴(조상 경로 포함).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.eff.col.state', 'FRONT', '컬럼 — 상태. 부여가 없는 행에서는 비어 있다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.eff.col.via', 'FRONT', '컬럼 — 출처. 역할명이거나 개인 예외다(backend/security.md 의 두 갈래).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.eff.empty', 'FRONT', '조회 결과가 비었다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.eff.gate', 'FRONT', '부여는 살아 있는데 **대상이 죽었다** — 게이트 ④(backend/security.md). 행의 배지 사유다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.eff.inactive', 'FRONT', '부여가 예정이거나 만료다 — 지금은 효력이 없다. 〃', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.eff.none', 'FRONT', '**유효 권한이 공집합이다** — 배너로 먼저 알린다(screen/admin/system/user/requirements.md). 그 계정은 **다음 로그인부터 차단된다**(backend/security.md). 탭을 열어 빈 표를 보고 유추하게 두지 않는다 — 빈 표는 *조회가 안 된 것* 으로도 읽힌다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.eff.scope', 'FRONT', '헤더 ⓐ 의 셀렉트 라벨 — 표시 범위(frontend/grid.md 의 `select` 첫 실물).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.eff.scope.all', 'FRONT', '범위 — 전체 메뉴. **없는 것도 보여야 한다**(screen/admin/system/user/requirements.md 의 요구 2). *"왜 못 보나"* 는 **권한이 없는 행**에 답이 있다 — 가진 것만 보여주면 이 탭은 진단이 아니라 요약이다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.eff.scope.held', 'FRONT', '범위 — 가진 것만. 기본값이다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.eff.title', 'FRONT', '탭 5 의 제목.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.eff.via.none', 'FRONT', '출처가 없다 — **부여 자체가 없는 행**이다(전체 메뉴 모드에서만 나온다).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.eff.via.personal', 'FRONT', '출처가 개인 예외다 — 서버가 보내는 `PERSONAL` 을 화면이 이 글자로 바꾼다.', NULL, NULL, NULL, NULL);
