INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.grant.empty', 'FRONT', '개인 예외가 하나도 없다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.grant.readonly', 'FRONT', '메뉴 컬럼의 헤더 툴팁 — **여기서는 고칠 수 없다**(screen/admin/system/user/requirements.md). 사용자 관리 권한이 있다고 예외 권한 부여 권한이 따라오면 안 되며, 권한은 `(MENU_CD, ACTION_CD)` 쌍이므로 **메뉴가 갈려야 갈린다**. 회색 그리드만 두면 *"왜 안 고쳐지나"* 가 된다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.grant.title', 'FRONT', '탭 2 의 제목.', NULL, NULL, NULL, NULL);
