INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.ip.col.ipCidr', 'FRONT', '컬럼 — 단일 IP 또는 CIDR. **PK 의 절반**이라 고치지 않고 지우고 다시 넣는다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.ip.col.useYn', 'FRONT', '컬럼 — 사용. **지우지 않고 끄는** 수단이다(sys/user-role.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.ip.col.validFromDt', 'FRONT', '컬럼 — 허용 기간의 시작(2026-08-31 · sys/user-role.md). **파견·출장처럼 기한이 있는 접근**이 이 기능의 둘째 용도다. 기간이 없으면 그 대역을 사람이 기억해서 지워야 하고, 잊으면 **끝난 계약의 IP 가 열려 있는 상태**가 된다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.ip.col.validToDt', 'FRONT', '〃 종료. **양끝 포함**이며 비우면 제한 없음이다(sys/INDEX.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.ip.duplicate', 'FRONT', '같은 대역이 이미 목록에 있다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.ip.empty', 'FRONT', '허용 대역이 하나도 없다 — **제한 없음이라고 말한다**(sys/user-role.md). *"등록된 대역이 없습니다"* 로 끝내면 **지금 이 계정이 어디서든 들어올 수 있다**는 사실을 아무도 말하지 않는다. 빈 화이트리스트를 전면 차단으로 읽는 오해가 정확히 반대편에 있고, 그 오해는 관리자 계정에서 사고가 된다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.ip.malformed', 'FRONT', 'IP 도 CIDR 도 아니다 — 서버가 다시 본다(frontend/grid.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.ip.period.tip', 'FRONT', '두 컬럼의 헤더 툴팁 — **판정 시각이 서버 기준**이라는 사실을 말한다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.ip.title', 'FRONT', '탭 3 의 제목.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.ip.warn.first', 'FRONT', '첫 대역을 더할 때의 경고 — **그 순간 나머지 전부가 막힌다**. 행이 없으면 제한 없음이므로(sys/user-role.md) 첫 행 하나가 **정책을 켜는 스위치**다. 건수는 *얼마나* 를 말할 뿐이라 그것을 말하지 못한다(screen/admin/system/code/requirements.md 가 연 자리). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.issued.desc', 'FRONT', '그 안내 — **이 창을 닫으면 다시 볼 수 없다**. 값이 응답에만 있기 때문이다(screen/admin/system/user/requirements.md). 말하지 않으면 관리자가 창을 닫고 나서 재발급을 누르는데, 그러면 방금 전한 값이 그 자리에서 무효가 된다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.issued.expiry', 'FRONT', '발급 값이 곧 만료된다는 안내 — `{hours}` 시간.', NULL, NULL, NULL, NULL);
