INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.search.roleExpiringInDays', 'FRONT', '조회조건 — 역할 만료 예정 N일. 숫자 칸이 아니라 **후보 콤보**다. 파생 조건은 부등호를 받지 못하므로(backend/api.md) *N일 이내* 라는 뜻을 번역 함수가 갖는다 — 그 김에 screen/admin/system/user/requirements.md 의 *기본값 미결* 이 **기본값 없음**으로 닫힌다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.search.roleId', 'FRONT', '조회조건 — 보유 역할. `EXISTS` 라 벤더 중립이다(screen/admin/system/user/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.search.userId', 'FRONT', '조회조건 — 로그인 ID. 앞 일치이며 PK 인덱스를 탄다(screen/admin/system/user/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.search.userNm', 'FRONT', '조회조건 — 이름. 부분 일치라 인덱스를 타지 않는다(screen/admin/system/user/requirements.md 미결).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.selfDisable', 'FRONT', '자기 계정의 사용 여부 셀을 끄려 했을 때 — **권한이 아니라 대상 제약**이다(screen/admin/system/user/requirements.md).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.session.col.clientIp', 'FRONT', '컬럼 — 접속 IP(2026-08-31). **세션 스토어에는 없는 값**이며 로그인 이력에서 온다. 담지 않고 조회 시점에 붙이므로 원본은 여전히 `SYS_LO_LOGIN` 하나다(sys/logs.md). /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.session.col.created', 'FRONT', '컬럼 — 생성 시각.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.session.col.current', 'FRONT', '컬럼 — 현재 세션인가. screen/admin/system/user/requirements.md 의 **자기 자신 금지**를 눈으로 확인시킨다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.session.col.expiry', 'FRONT', '컬럼 — 만료 예정 = 최근 접근 + 유휴 한도. **파생**이다.', NULL, NULL, NULL, NULL);
