INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.session.col.sessionId', 'FRONT', '컬럼 — 세션. **앞 8자만** 그린다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.session.col.userAgent', 'FRONT', '〃 브라우저(`User-Agent`). `VARCHAR(500)` 이라 셀에서 잘리고 툴팁으로 펼친다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.session.empty', 'FRONT', '활성 세션이 없다 — 지금 아무 데도 들어와 있지 않다.', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.session.fromLogin', 'FRONT', '두 컬럼의 헤더 툴팁 — **출처를 말한다**(screen/admin/system/log/access/requirements.md 과 같은 규약). 이 컬럼을 어디까지 믿을 수 있나가 값의 옆에 없으면, **빈 칸이 결함으로** 읽히고 채워진 칸은 세션이 들고 있는 사실처럼 읽힌다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.session.kill', 'FRONT', '실행 버튼 — 강제 종료(AUTH-10).', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.session.kill.confirm', 'FRONT', '확인 문구 — **계정은 바뀌지 않는다**는 것을 말한다(screen/admin/system/user/requirements.md). *"N건을 종료합니다"* 만으로는 **다시 로그인할 수 있다**는 사실이 빠진다 — 막으려면 `USE_YN=''N''` 이고 그것은 **다른 축**이다(sys/user-role.md). 말하지 않으면 이 버튼이 계정을 잠그는 것으로 읽힌다. /', NULL, NULL, NULL, NULL);
INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('user.session.kill.done', 'FRONT', '결과 — `{count}` 건을 끊었다. **고른 수와 다를 수 있고 다른 것이 사실**이다.', NULL, NULL, NULL, NULL);
