INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('userAuth.col.grantCnt', 'FRONT', '좌 pane 컬럼 — **지금 유효한** 예외 건수(screen/admin/system/user/requirements.md). 예정·만료를 세지 않는 것이 이름에 들어가야 했다 — *예외 건수* 로 두면 만료가 쌓인 계정에서 **화면의 어느 수와도 맞지 않는다**. /', NULL, NULL, NULL, NULL);
