INSERT INTO sys_message_key (msg_key, use_scope, msg_desc, reg_id, reg_dtm, mod_id, mod_dtm) VALUES ('userAuth.period.reversed', 'FRONT', '시작일이 종료일보다 늦다. **비어 있는 것은 여기서 말하지 않는다** — 컬럼의 `required` 가 그리드 공용 문구 (`grid.validation.required`)를 낸다(frontend/grid.md). 같은 말을 화면마다 다시 적으면 그것이 곧 번역해야 할 문장이 하나 더 느는 일이다. /', NULL, NULL, NULL, NULL);
