INSERT INTO sys_schedule_batch (batch_id, batch_nm, batch_desc, bean_id, cron, param_json, lock_expiry_sec, lock_min_interval_sec, use_yn, sort_no, reg_id, reg_dtm, mod_id, mod_dtm, timezone) VALUES ('RETENTION_PURGE', '이력 보존 파기', '보관 기간이 지난 감사·추적 이력을 지운다 — 사용 이력 90일 · 에러 로그 180일 · 로그인 이력 1년 · 배치 실행 이력 1년(32 §3, 시스템 환경설정에서 바꾼다). 삭제는 되돌릴 수 없고 아카이브는 아직 없다 — 켜기 전에 보존 기간과 아카이브 방침을 먼저 정한다.', 'retentionPurgeJob', '0 30 3 * * *', NULL, 300, 0, 'N', 10, 'SYSTEM', '2026-09-13 13:00:05.588299+09', NULL, NULL, 'Asia/Seoul');
INSERT INTO sys_schedule_batch (batch_id, batch_nm, batch_desc, bean_id, cron, param_json, lock_expiry_sec, lock_min_interval_sec, use_yn, sort_no, reg_id, reg_dtm, mod_id, mod_dtm, timezone) VALUES ('EXPIRY_NOTICE', '만료 예고 알림', '비밀번호와 권한의 만료를 미리 알린다 — 비밀번호는 만료 예고일 기준(AUTH-05), 권한은 역할 부여와 개인 예외의 유효 종료일 기준(AUTHZ-08). 만료를 처리하지는 않는다: 판정은 조회 시 계산이며(23 §4) 이 배치는 알림만 넣는다. 끄면 사용자가 만료를 미리 알 수 없고, 설정의 예고 일수가 아무 일도 하지 않게 된다.', 'expiryNoticeJob', '0 10 4 * * *', NULL, 60, 0, 'Y', 20, 'SYSTEM', '2026-09-13 13:00:05.736865+09', NULL, NULL, 'Asia/Seoul');
